quickStart.code:
import { runner } from '@epdoc/cmd';

const result = await runner('git', ['status', '--short'])
  .cwd('/my/repo')
  .run();
if (result.success) console.log(result.stdout);

patterns.code:
const result = await runner('node', ['script.js'])
  .outParser(s => JSON.parse(s) as MyType)
  .run();
console.log(result.data.property);

const result = await runner('tool', ['--json'])
  .errParser((result) => new MyError(JSON.parse(result.stderr)))
  .run();
if (result.error) throw result.error;

const data = await runner('exiftool', ['-j', 'photo.jpg'])
  .outParser(s => JSON.parse(s) as Metadata[])
  .orThrow();

class DenoRunner extends Runner {
  constructor(args, opts) { super('deno', args, opts); }
}
